import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"51、【震】 震下震上","description":"周易尚氏學 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"周易尚氏學 - 51、【震】 震下震上"},"headers":[],"relativePath":"classics/shangshi/056.md","filePath":"classics/shangshi/056.md"}'),h={name:"classics/shangshi/056.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><p>震振也。動也。一陽伏二陰之下。陽必上升。故振動而為雷。為起。歸藏作釐。李過曰釐者理也。黃宗炎曰謂雷釐地而出以作聲。愚按震為笑樂。為喜。而釐與僖通。史記以魯僖公釐公。是其證。說文。傅樂也。與喜同。又震為生為福。而釐亦為福。前漢文帝紀祠官祝釐如淳曰福也。是釐與震義多同。故歸藏作釐。周易作震。陽得出故亨。aa？恐懼貌。陽來居初。故日震來。雷之發也。萬物震恐。故震來a？a？ 。陽遇陰則通。故笑言啞啞。啞啞笑貌。震為百。艮為裡。坎為棘匕。為鬯。鬯櫃（左禾）酒也。震為黍。坎為酒。故曰鬯。震驚百里。不喪匕鬯者。言震雷雖威及百里。而不驚懼也。匕所以載牲。曾所以降神。皆祭祀之用。故傳曰可以守宗廟為祭主也。</p><p>彖曰。震亨。震來。恐致福也。笑言啞啞。後有則也。震驚百里。驚遠而懼邇也。出可以守宗廟社稷。以為祭主也。</p><p>震為福。故曰恐致福。則。法也。互坎為法則。震為後。後有則者。言陽復於下為陰主也。震為出。為祭。為主。艮為守。為社稷。為廟。震為長子。驚遠懼邇。能匕鬯不失。故可為祭主。而長守宗廟社稷也。</p><h3 id="洊雷震。君子以恐懼修省。" tabindex="-1">洊雷震。君子以恐懼修省。 <a class="header-anchor" href="#洊雷震。君子以恐懼修省。" aria-label="Permalink to “洊雷震。君子以恐懼修省。”">​</a></h3><p>洊再也。上下震故曰洊雷。 困震而恐，因恐而修省。</p><p>初九。震來虩虩， 後笑言啞啞。吉。</p><p>陽在下。故曰後。言初雖aa？恐懼，後則樂也。陽遇重陰故也。</p><h3 id="象曰。震來虩虩-恐致福也。笑言啞啞。後有則也。" tabindex="-1">象曰。震來虩虩，恐致福也。笑言啞啞。後有則也。 <a class="header-anchor" href="#象曰。震來虩虩-恐致福也。笑言啞啞。後有則也。" aria-label="Permalink to “象曰。震來虩虩，恐致福也。笑言啞啞。後有則也。”">​</a></h3><p>恐則修省。修省則致福。</p><p>震來厲，億喪貝，躋於九陵。勿逐，七日得。</p><p>來者復也。震來厲。言陽復初。二乘之。故危厲不安也。億噫通。釋文雲。本亦作噫。虞翻雲。惜辭也。艮為貝。震者艮之覆。故喪貝。古以貝為貨幣。因厲喪貝。震為言。故曰惜辭。鄭作十萬解。似不如虞義也。二至四艮。艮為陵。艮陽在上。陽老故曰九陵。震為臍。躍升也。而坎為盜。在艮陵上。言有人持貝。臍九陵以去也。然不必逐也。震為逐。數七。故曰七日。震為復。勿逐七日得者。言所喪之貝。不必追逐。至七日自然來複也。舊解皆以離為貝。易林剝之蒙雲。齊貝贖狸。蒙上艮為齊為貝。又謙之蠱。訟之大畜。皆曰喪貝。亦皆以上艮為貝。蓋艮堅在外。與離同也。</p><h3 id="象曰。震來厲-乘剛也。" tabindex="-1">象曰。震來厲，乘剛也。 <a class="header-anchor" href="#象曰。震來厲-乘剛也。" aria-label="Permalink to “象曰。震來厲，乘剛也。”">​</a></h3><p>乘剛故危。</p><p>六三。震蘇蘇。震行無眚。</p><p>蘇蘇。鄭雲不安也。坎為疾病。故為眚蓋三不當位。故不安。然得陽為承。亦無眚也。</p><h3 id="象曰。震蘇蘇。位不當也。" tabindex="-1">象曰。震蘇蘇。位不當也。 <a class="header-anchor" href="#象曰。震蘇蘇。位不當也。" aria-label="Permalink to “象曰。震蘇蘇。位不當也。”">​</a></h3><p>虞以蘇為死而復生。由象傳觀之。鄭釋為當。</p><p>九四。震遂泥。</p><p>遂隧之省文。隧即墜也。論語文武之道。未墜於地。石經作隊。又列子。矢隧地而塵不揚。皆以隧為墜。遂古文隧之省。荀子理論篇。人焉而隧。楊驚注云。隧古墜字。故荀爽作隧。四坎為泥。陷四陰中。故隧泥。震為行。隧泥則行難矣。</p><h3 id="象曰。震遂泥。未光也。" tabindex="-1">象曰。震遂泥。未光也。 <a class="header-anchor" href="#象曰。震遂泥。未光也。" aria-label="Permalink to “象曰。震遂泥。未光也。”">​</a></h3><p>坎隱伏。故未光。</p><p>六五。震往來厲，億無喪，有事。</p><p>往得敵。來乘陽。故往來皆危厲也。自陽遇陽陰遇陰為敵之理失傳。於是虞翻不知往厲之故在陰遇陰。只以乘剛為說。乘剛則來厲。於往無涉也。五得中位尊。匕鬯之事。故無喪也。</p><h3 id="象曰。震往來厲。危行也。其事在中。大無喪也。" tabindex="-1">象曰。震往來厲。危行也。其事在中。大無喪也。 <a class="header-anchor" href="#象曰。震往來厲。危行也。其事在中。大無喪也。" aria-label="Permalink to “象曰。震往來厲。危行也。其事在中。大無喪也。”">​</a></h3><p>行。道也。大無喪即億無喪。</p><p>上六。震索索。視矍矍。徵兇。震不於其躬。於其鄰。無咎。</p><p>婚媾有言。索索。鄭雲猶縮縮。足不正也。三在震上。蘇蘇不安。上亦同也。？？。鄭雲目不正也。說文。佳欲逸走也。徐曰。左右驚顧也。震。目無上皆。故因恐懼而視矍矍也。易林訟之豫雲。眵難無距。與鵲格鬥。翅折目盲。為鳩所傷。眵。說文目傷目（上此）也。豫上震。目無上目（上此）。故日眵。曰盲。義即本此也。虞翻不知易用象之妙。以卦無視象。命三變成離取視象。易取象無此迂曲也。三無應。故徵兇。震不於其躬於其鄰。仍驚遠懼邇之意。艮為躬。艮覆為震。故不於其躬於其鄰。震為鄰。易林蹇之噬嗑雲。不利出鄰。疾病憂患。噬嗑下震為鄰為出。出即與坎險遇。而有疾病憂患之苦。是明以震為鄰也。鄰仍謂三也。言三蘇蘇。即知其可懼而戒備也。知懼故無咎。卦二至上正反震。故有言。有言者爭訟。與困之三至上正反兌有言不信同也。卦三男俱備。無一女象。故不能婚媾。如婚媾則必爭訟也。自覆象失傳。此句舊解二千年無一當者。只易林中孚之謙雲。伯氏爭言。謙亦正覆震。與震二至上同。爭言即有言。震為伯也。</p><h3 id="象曰。震索索。中未得也。雖兇無咎。畏鄰戒也。" tabindex="-1">象曰。震索索。中未得也。雖兇無咎。畏鄰戒也。 <a class="header-anchor" href="#象曰。震索索。中未得也。雖兇無咎。畏鄰戒也。" aria-label="Permalink to “象曰。震索索。中未得也。雖兇無咎。畏鄰戒也。”">​</a></h3><p>在震上。故曰中未得。因畏而戒。故無咎。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
